#!/usr/bin/env python3
"""Generate a self-contained status snapshot; no external scripts, no fake activity."""
from pathlib import Path
import datetime as dt,json,html
ROOT=Path(__file__).resolve().parents[1]

def render(root=ROOT):
    root=Path(root);states=[]
    for agent in ('kinetic','scribble','axiom','parallax','glyphcraft'):
        path=root/'status'/(agent+'.json')
        states.append(json.loads(path.read_text()))
    data=json.dumps(states,ensure_ascii=False).replace('</','<\\/');stamp=dt.datetime.now(dt.timezone.utc).isoformat(timespec='seconds')
    page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Frameforge — five independent film slots</title><style>
*{box-sizing:border-box}body{margin:0;background:#10131b;color:#eceef3;font:16px/1.5 system-ui,sans-serif}main{max-width:1120px;margin:auto;padding:48px 24px}h1{font-size:48px;letter-spacing:-2px;line-height:1.05;margin:8px 0 18px}p{color:#b4bdce}small{color:#909caf}.eyebrow{font:12px ui-monospace,monospace;letter-spacing:3px;color:#70dfbe}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:18px;margin-top:32px}article{border:1px solid #313b50;border-radius:18px;padding:24px;background:#191f2b;min-width:0}h2{text-transform:capitalize;margin:0 0 16px;font-size:27px}.badge{display:inline-block;padding:4px 10px;border-radius:40px;background:#343e52;color:#f4f4f4;font-size:12px;margin-bottom:12px}.good{background:#194939}.stale{background:#673b20}.bad{background:#67313b}.label{font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#8293ac;margin:17px 0 4px}a{color:#8de1cb}code{font-size:12px;color:#b9cde0;overflow-wrap:anywhere}.footer{margin-top:30px;border-top:1px solid #344053;padding-top:22px}@media(max-width:760px){.cards{grid-template-columns:1fr}h1{font-size:37px}}
</style><main><div class="eyebrow">FRAMEFORGE / DIRECTOR'S CONSOLE</div><h1>Five independent slots.<br>Two Kinetic successors.</h1><p>No shared dependency queue. No simulated presence. A commissioned slot is not an awake agent.<br>Primary media archive: storagecode. OUTPOST MARS stays paused.</p><div class="cards" id="cards"></div><div class="footer"><p id="stamp"></p><p>This is an embedded snapshot. When served over HTTP(S), it tries all five public status files. Network failure leaves the snapshot visible, explicitly not live. Staleness is calculated from timestamps, not optimistic labels. A green process marker means only an observed child process, never continuous AI thought.</p><a href="https://github.com/dreamer2664/frameforge">Code &amp; clean briefs</a> · <a href="https://github.com/dreamer2664/storagecode">Primary media archive</a></div></main><script>
const embedded=__DATA__;let records=embedded;const made=__STAMP__;let source='Embedded snapshot';const esc=s=>String(s||'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function draw(){document.getElementById('cards').innerHTML=records.map(s=>{const age=Math.max(0,(Date.now()-Date.parse(s.updated_at))/1000);let label=s.state,cls='';if(['working','process-running'].includes(s.state)){label=age>600?'STALE — no recent observation':(age>330?'Heartbeat overdue':s.state);cls=age>600?'bad':age>330?'stale':'good'}else if(s.state==='delivered'){cls='good'}const names={kinetic:'Kinetic type / premium motion',scribble:'Vertical stickman explanations',axiom:'Long-form illustrated questions',parallax:'Kinetic successor / spatial typography',glyphcraft:'Kinetic successor / living letterforms'};return `<article><h2>${esc(s.agent)}</h2><span class="badge ${cls}">${esc(label)}</span><p>${esc(names[s.agent])}</p><div class="label">Stage</div><div>${esc(s.stage)}</div><div class="label">Last observed activity</div><div>${esc(s.observed_activity)}</div><div class="label">Updated (UTC)</div><code>${esc(s.updated_at)} · ${Math.floor(age/60)}m ago</code><div class="label">Next concrete step</div><div>${esc(s.next_action)}</div><div class="label">Action / failure / handoff log</div><a href="https://github.com/dreamer2664/frameforge/blob/main/agents/${esc(s.agent)}/HANDOFF.md">${esc(s.agent)}/HANDOFF.md</a></article>`}).join('');document.getElementById('stamp').textContent=source+' · snapshot built '+made;}
draw();setInterval(draw,1000);function sync(){if(/^https?:$/.test(location.protocol)){Promise.all(['kinetic','scribble','axiom','parallax','glyphcraft'].map(a=>fetch('https://raw.githubusercontent.com/dreamer2664/frameforge/main/status/'+a+'.json?_='+Date.now()).then(r=>{if(!r.ok)throw Error();return r.json()}))).then(s=>{records=s;source='Public status fetched at '+new Date().toISOString();draw()}).catch(()=>{source='Last successful status snapshot — live fetch unavailable';draw()})}}sync();setInterval(sync,60000);
</script></html>'''.replace('__DATA__',data).replace('__STAMP__',json.dumps(stamp))
    target=root/'STATUS.html';target.write_text(page);(root/'index.html').write_text(page);return target
if __name__=='__main__':print(render())
